def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = tuple(h[1] for h in history)
    me = tuple(h[0] for h in history)
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    me_c = sum(1 for a in me if a == 'C')
    me_d = n - me_c

    recent = opp[-12:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_d = len(recent) - recent_c

    last_opp = opp[-1]
    last_me = me[-1]

    if opp_d == 0:
        if n < 20:
            return 'C'
        if n < 80:
            return 'C' if rng.random() < 0.98 else 'D'
        return 'C' if rng.random() < 0.92 else 'D'

    if recent_d >= 9:
        return 'D'

    if recent_c >= 10 and opp_d <= max(2, n // 20):
        if rng.random() < 0.93:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if recent_d >= 4 or rng.random() < 0.3:
                return 'D'
            return 'C'
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    if recent_d >= 5:
        if recent_c >= 3:
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        return 'D'

    if n >= 12:
        if opp_c >= 2 * opp_d:
            return 'C'
        if opp_d >= 2 * opp_c:
            return 'D'
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    return 'C'
